	startRow := group*4 + 1

	// Calculate the time taken to reach the start of the group
	// Each group takes 6 seconds to serve (3 rows * 2 attendants)
	// Plus movement time between groups
	timeToGroup := group * (6 + 1) // 6 seconds serving, 1 second moving

	// Calculate the time within the group
	// The first attendant serves rows startRow and startRow+2
	// The second attendant serves startRow+1 and startRow+3
	// But we need to determine which attendant serves row n

