	"strings"
)

func main() {
	var s string
	fmt.Scan(&s)
	n, _ := strconv.ParseInt(s[:len(s)-1], 10, 64)
	seat := s[len(s)-1]

	// Determine the order of serving seats
	// Right side first (f, e, d), then left side (a, b, c)
	// Each seat has a position in the serving order (1-based)
	var pos int
	switch seat {
	case 'f':
		pos = 1
	case 'e':
		pos = 2
	case 'd':
		pos = 3
	case 'a':
		pos = 4
	case 'b':
		pos = 5
	case 'c':
		pos = 6
	}

	// Determine which attendant serves this row and the time taken
	// Attendant 1 serves rows 1, 2, 5, 6, 9, 10, ...
	// Attendant 2 serves rows 3, 4, 7, 8, 11, 12, ...
	// The pattern repeats every 4 rows: 1,2 then 3,4 then 5,6 then 7,8 etc.
	// For a given row n, we need to find out which group it belongs to
	// and the time taken to reach that row.

	// Calculate the group and position within the group
	// Groups are formed as (1,2), (3,4), (5,6), (7,8), ...
	// Each group has 2 rows, and there are 6 seats per row, so 12 seats per group
	// Time to serve a group: 12 seconds (6 seats * 2 rows)
	// Time to move between groups: 1 second (move 1 row forward)
	// But the movement pattern is: serve 1,3 then move 1 row to 2,4 then move 3 rows to 5,7 etc.

	// Let's think differently:
	// The attendants serve in pairs: (1,3), (2,4), (5,7), (6,8), (9,11), (10,12), ...
	// Each pair takes 12 seconds to serve (6 seats each)
	// Between pairs, they move:
	// - After (1,3), move 1 row to (2,4): 1 second
	// - After (2,4), move 3 rows to (5,7): 3 seconds
	// - After (5,7), move 1 row to (6,8): 1 second
	// - After (6,8), move 3 rows to (9,11): 3 seconds
	// Pattern of movement: 1, 3, 1, 3, ...

	// For row n, we need to find which pair it's in and the cumulative time

	// Let's find the pair index
	// Pairs are: (1,3), (2,4), (5,7), (6,8), (9,11), (10,12), ...
	// Pair 0: rows 1, 3
	// Pair 1: rows 2, 4
	// Pair 2: rows 5, 7
	// Pair 3: rows 6, 8
	// Pair 4: rows 9, 11
	// Pair 5: rows 10, 12
	// ...

	// For a given row n, find which pair it belongs to
	// Pairs come in groups of 2: (1,3)&(2,4), (5,7)&(6,8), (9,11)&(10,12), ...
	// Each group of 2 pairs covers 4 rows: 1-4, 5-8, 9-12, ...
	// Within a group, first pair is (start, start+2), second pair is (start+1, start+3)

	// Find which group of 4 rows n belongs to
	group := (n - 1) / 4 // 0-indexed group
	startRow := group*4 + 1

	// Determine if n is in the first or second pair of this group
	var pairInGroup int
	if n == startRow || n == startRow+2 {
		pairInGroup = 0
	} else {
		pairInGroup = 1
	}

	// Calculate the pair index
	pairIndex := group*2 + pairInGroup

	// Calculate time to reach this pair
	// Each pair takes 12 seconds to serve
	// Movement time between pairs: 1, 3, 1, 3, ...
	// Pair 0: no movement before, serve time = 12
	// Pair 1: movement = 1, serve time = 12
	// Pair 2: movement = 3, serve time = 12
	// Pair 3: movement = 1, serve time = 12
	// Pair 4: movement = 3, serve time = 12
	// ...

	// Time = sum of all previous serve times + sum of all previous movements + current serve time up to this row

	// Total time before this pair starts serving
	// Serve time for all previous pairs: pairIndex * 12
	// Movement time: for pairs 1 to pairIndex, alternating 1 and 3
	// Movement for pair i (1-indexed): if i is odd, 1; if even, 3
	// But pairIndex is 0-indexed, so movement for pair j (1-indexed from 1 to pairIndex):
	// if j is odd (1st, 3rd, 5th...), movement = 1
	// if j is even (2nd, 4th, 6th...), movement = 3

	// Actually, let me re-examine:
	// Before pair 0: no movement
	// Before pair 1: move 1 row (from pair 0's rows to pair 1's rows)
	// Before pair 2: move 3 rows
	// Before pair 3: move 1 row
	// Before pair 4: move 3 rows
	// ...

	// Movement before pair j (j >= 1):
	// if j is odd: 1
	// if j is even: 3

	// Sum of movements before pair pairIndex:
	// For j from 1 to pairIndex:
	// if j is odd: add 1
	// if j is even: add 3

	// Number of odd j's from 1 to pairIndex: (pairIndex + 1) / 2
	// Number of even j's from 1 to pairIndex: pairIndex / 2
	// Total movement = ((pairIndex + 1) / 2) * 1 + (pairIndex / 2) * 3

	movementTime := ((pairIndex + 1) / 2) * 1 + (pairIndex / 2) * 3
	serveTimeBefore := pairIndex * 12

	// Time when this pair starts serving
	startTime := movementTime + serveTimeBefore

	// Now, within this pair, determine which row is served first
	// Pair 0: rows 1, 3 -> row 1 first
	// Pair 1: rows 2, 4 -> row 2 first
	// Pair 2: rows 5, 7 -> row 5 first
	// Pair 3: rows 6, 8 -> row 6 first
	// ...

	// For pairInGroup 0: first row is startRow, second is startRow+2
	// For pairInGroup 1: first row is startRow+1, second is startRow+3

	var firstRow, secondRow int
	if pairInGroup == 0 {
		firstRow = startRow
		secondRow = startRow + 2
	} else {
		firstRow = startRow + 1
		secondRow = startRow + 3
	}

	// Determine if n is the first or second row in the pair
	var rowOffset int
	if n == firstRow {
		rowOffset = 0
	} else {
		rowOffset = 6 // second row in pair, 6 seconds after first row starts
	}

	// Time when this row starts being served
	rowStartTime := startTime + rowOffset

	// Time when Vasya is served (pos is 1-indexed, so pos-1 seconds after row starts)
	result := rowStartTime + (pos - 1)

	fmt.Println(result)
	_ = strings.TrimSpace
}
