	// Each group takes 6 seconds to serve (3 seats per row * 2 rows)
	// Plus 1 second to move to the next group

	// Find which group the row belongs to
	// Groups alternate between starting at odd and even rows
	// Group 1: rows 1, 3
	// Group 2: rows 2, 4
	// Group 3: rows 5, 7
	// Group 4: rows 6, 8
	// ...

	// Determine the group number
	var groupNum int
	if n%2 == 1 {
		// Odd row
		groupNum = (n + 1) / 2
	} else {
		// Even row
		groupNum = n / 2
	}

	// Calculate the total time
	// Each group takes 6 seconds to serve + 1 second to move (except the first group)
	// The first group starts at time 0
