	// But we need to find the time when Vasya's row is being served

	// Within a group, the first row is served first, then the second row
	// The first row in a group is served at time (groupNum-1)*7
	// The second row in a group is served at time (groupNum-1)*7 + 6

	var time int
	if n%2 == 1 {
		// Odd row: first row in the group
		time = (groupNum - 1) * 7
	} else {
		// Even row: second row in the group
