package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	var input string
	fmt.Scan(&input)
	n, _ := strconv.ParseInt(input[:len(input)-1], 10, 64)
	seat := input[len(input)-1]

	// Determine the seat's position in the serving order
	var seatOrder int
	switch seat {
	case 'f':
		seatOrder = 1
	case 'e':
		seatOrder = 2
	case 'd':
		seatOrder = 3
	case 'a':
		seatOrder = 4
	case 'b':
		seatOrder = 5
	case 'c':
		seatOrder = 6
	}

	// Determine which attendant serves the row and the time taken to reach that row
	var totalTime int64
	if n%2 == 1 {
		// Attended by the first attendant
		k := (n - 1) / 2
		// Time for all previous groups: each group takes 6 seconds (serving) + 1 second (moving)
		// But the first group (k=0) doesn't have a prior move
		totalTime = k * 7
		// Add the time to serve up to this seat in the current row
		totalTime += int64(seatOrder)
	} else {
		// Attended by the second attendant
		k := (n - 2) / 2
		// Time for all previous groups: each group takes 6 seconds (serving) + 1 second (moving)
		// The first group (k=0) doesn't have a prior move
		totalTime = k * 7
		// Add the time to serve up to this seat in the current row
		totalTime += int64(seatOrder)
	}

	fmt.Println(totalTime)
}
